<script setup lang="ts">
import {computed,ref} from 'vue'
import UiDialog from '@/components/ui/UiDialog.vue'
import UiButton from '@/components/ui/UiButton.vue'
import UiSelectField from '@/components/ui/UiSelectField.vue'
import ObjectScopeTree from './ObjectScopeTree.vue'
import type {RefV2} from '@/features/models/api-v2'
import type {PreviewV2,ObjectEntryV2,CatalogV2,ScopeRequestV2} from './api-v2'
const props=defineProps<{open:boolean;preview:PreviewV2|null;entries?:readonly ObjectEntryV2[];busy?:boolean;error?:string;stale?:boolean;workspace?:boolean;catalog?:CatalogV2|null;scope?:ScopeRequestV2;loading?:boolean;scopeError?:string;hasResult?:boolean}>()
const emit=defineEmits<{close:[];direction:[value:'upload'|'download'];backup:[value:boolean];confirm:[];retry:[];catalog:[read:string|null,write:string|null];prepare:[read:string|null,write:string|null];toggle:[entry:ObjectEntryV2,value:boolean];mcp:[name:string,client:string];subset:[channelId:string,kind:'all'|'models'|'families',ids:string[]];option:[channelId:string,field:'includeConnection'|'includeKey'|'includeAuthorization',value:boolean];credential:[entry:ObjectEntryV2,value:boolean];result:[];recovery:[];connection:[];revision:[reference:RefV2,value:boolean];default:[reference:RefV2,value:boolean];global:[value:boolean]}>()
const search=ref(''),readPassphrase=ref(''),writePassphrase=ref(''),useProtection=ref(false)
const entries=computed(()=>props.catalog?.entries??[])
const key=(e:ObjectEntryV2)=>JSON.stringify([e.kind,e.id])
const categories={channel:'channels',template:'templates',account:'accounts',skill:'skills',mcp:'mcps',preferences:'manager',extensions:'manager'}
const objects=computed(()=>entries.value.map(e=>({id:key(e),category:categories[e.kind],categoryLabel:kinds[e.kind],label:e.label,detail:e.kind==='mcp'&&e.id==='node_repl'?'由客户端应用维护 · 含本机路径':e.kind==='channel'?'服务节点、模型选择与配置':'',mark:e.availableLocal&&e.availableCloud?'本机 / 云端':e.availableLocal?'本机可读':'云端可读'})))
const selectedIds=computed(()=>entries.value.filter(selected).map(key))
function entryFor(id:string){return entries.value.find(e=>key(e)===id)}
function updateIds(ids:string[]){const next=new Set(ids);for(const e of entries.value)if(selected(e)!==next.has(key(e)))emit('toggle',e,next.has(key(e)))}
function selected(entry:ObjectEntryV2){const s=props.scope?.selection;if(!s)return false;switch(entry.kind){case'channel':return s.channels.some(c=>c.portableChannelId===entry.id);case'template':return s.templateRefs.some(r=>r.templateId===entry.id);case'preferences':return s.manager.preferences;case'extensions':return s.manager.extensions;case'account':return s.manager.accountIds.includes(entry.id);case'skill':return s.skillNames.includes(entry.id);case'mcp':return s.mcpSources.some(m=>m.name===entry.id)}}
function channel(id:string){return props.scope?.selection.channels.find(c=>c.portableChannelId===id)}
function subset(entry:ObjectEntryV2,kind:'all'|'models'|'families'){emit('subset',entry.id,kind,kind==='models'?[...entry.modelIds]:kind==='families'?[...entry.familyIds]:[])}
function toggleSubset(entry:ObjectEntryV2,kind:'models'|'families',id:string,value:boolean){const chosen=kind==='models'?channel(entry.id)?.modelIds:channel(entry.id)?.familyIds;const ids=(chosen??[]).filter(n=>n!==id);if(value)ids.push(id);emit('subset',entry.id,kind,ids)}
const kinds={channel:'渠道与模型',template:'模型模版',preferences:'管理器偏好',extensions:'扩展配置',account:'账户信息',skill:'Skill',mcp:'MCP'}
function submit(kind:'catalog'|'prepare'){const read=readPassphrase.value||null,write=useProtection.value?(writePassphrase.value||null):null;if(kind==='prepare')emit('prepare',read,write);else emit('catalog',read,write);readPassphrase.value='';writePassphrase.value=''}
const initialization=computed(()=>props.preview?.plan.kind==='upload'&&props.preview.plan.plan.initialization==='on_confirm')
const disabled=computed(()=>!!props.busy||!!props.error||!!props.stale||!props.preview||props.preview.noChange||props.preview.plan.kind==='no_change'||props.preview.entries.some(e=>e.status==='unavailable'||e.status==='source_required'))
const actionLabel=computed(()=>initialization.value?'初始化并上传':props.preview?.chosenDirection==='download'?'确认下载':'确认上传')
function savedTime(value:string|null|undefined){return value&&Number.isFinite(Date.parse(value))?value:'未知'}
function label(kind:string,id:string){return props.entries?.find(e=>e.kind===kind&&e.id===id)?.label??id}
const changes={add:'新增',update:'更新',unchanged:'不变',unavailable:'来源暂不可用',source_required:'需要明确来源'}
const reasonText={same_semantic_content:'所选内容一致，无需更新。',both_empty:'两侧均没有所选内容。',cloud_empty:'已核实云端暂无有效配置，默认上传。',local_empty:'本机暂无所选内容，云端有效配置可下载。',local_saved_later:'按可靠业务保存时间预选上传。',cloud_saved_later:'按可靠业务保存时间预选下载。',unreliable_save_time:'保存时间不足以判新；云端有有效配置，默认下载。',equal_time_different_content:'业务保存时间相同但内容不同；按本次明确方向预览。',explicit_upload:'本次明确以上传来源预览。',explicit_download:'本次明确以下载来源预览。'}
function errorMessage(value:string|undefined){if(value==='sync_passphrase_required')return '请输入云端配置的保护口令。';return value&&/^[a-z][a-z0-9_]+$/.test(value)?'本次操作未完成，请重试；当前选择与已有配置保持。':value}
</script>
<template>
  <section v-if="workspace" class="config-sync-workspace-v2" aria-label="WebDAV配置同步">
    <div class="sync-workspace-toolbar"><div><h2>设备间同步</h2><p>较新版本覆盖所选范围，确认前可查看变化。</p></div><div class="sync-workspace-actions"><UiButton v-if="hasResult" @click="emit('result')">查看原操作</UiButton><UiButton variant="primary" :disabled="loading||busy||!catalog||catalog.cloudState==='initialization_ambiguous'" @click="submit('prepare')">同步</UiButton><details class="sync-more"><summary class="btn">更多</summary><div class="sync-more-actions"><UiButton :disabled="loading||busy" @click="submit('catalog')">重新读取目录</UiButton></div></details></div></div>
    <slot name="connection" />
    <p v-if="loading" role="status">正在读取有效配置目录…</p><p v-if="error&&!open" class="model-error" role="alert">{{errorMessage(error)}}</p><p v-if="scopeError" class="model-error" role="alert">{{errorMessage(scopeError)}}</p>
    <p v-if="catalog&&['conflict','initialization_ambiguous'].includes(catalog.cloudState)" class="model-error" role="alert">{{catalog.cloudState==='conflict'?'云端有并发提交，须明确选择来源后预览。':'多个初始化代次，普通写入已停止。'}}<UiButton size="sm" @click="emit('recovery')">查看恢复动作</UiButton></p>
    <div v-if="catalog" class="sync-scope-workspace"><section class="sync-scope"><div class="sync-search"><input v-model="search" class="input" type="search" aria-label="搜索同步对象" placeholder="搜索配置对象" /></div><ObjectScopeTree :objects="objects" :selected-ids="selectedIds" :query="search" label="同步配置对象" name-label="同步范围" :disabled="busy||loading" @update:selected-ids="updateIds"><template #options="{object}"><template v-for="entry in entryFor(object.id)?[entryFor(object.id)!]:[]" :key="entry.kind+entry.id">
      <template v-if="entry.kind==='channel'&&selected(entry)"><div class="sync-workspace-options"><UiSelectField :model-value="channel(entry.id)?.modelIds!==null?'models':channel(entry.id)?.familyIds!==null?'families':'all'" :label="entry.label+'模型范围'" :disabled="busy" :options="[{value:'all',label:'全渠道模型'},{value:'models',label:'逐模型选择'},{value:'families',label:'按模型族片段'}]" @update:model-value="subset(entry,$event as 'all'|'models'|'families')" /><label><input type="checkbox" :checked="channel(entry.id)?.includeConnection" :disabled="busy||channel(entry.id)?.familyIds!==null" @change="emit('option',entry.id,'includeConnection',($event.target as HTMLInputElement).checked)" />包含连接</label></div>
      <div v-if="channel(entry.id)?.modelIds!==null" class="sync-model-subset"><label v-for="model in entry.models" :key="model.rawModelId"><input type="checkbox" :checked="channel(entry.id)?.modelIds?.includes(model.rawModelId)" :disabled="busy" @change="toggleSubset(entry,'models',model.rawModelId,($event.target as HTMLInputElement).checked)" />{{model.label||model.rawModelId}}<code>{{model.rawModelId}}</code></label></div>
      <div v-if="channel(entry.id)?.familyIds!==null" class="sync-model-subset"><label v-for="family in entry.familyIds" :key="family"><input type="checkbox" :checked="channel(entry.id)?.familyIds?.includes(family)" :disabled="busy" @change="toggleSubset(entry,'families',family,($event.target as HTMLInputElement).checked)" />{{family}}</label></div></template>
      <template v-if="entry.kind==='mcp'"><UiSelectField :model-value="scope?.mcpClients[entry.id]??''" :label="entry.label+'定义来源'" :disabled="busy" :options="[{value:'',label:'请选择明确来源 / 暂不同步'},...(catalog.mcpSources.find(m=>m.name===entry.id)?.sources??[]).map(s=>({value:s.source,label:s.source==='managed'&&!entry.availableLocal?'云端配置（下载到本机托管）':s.source}))]" @update:model-value="emit('mcp',entry.id,$event)" /><p v-if="catalog.mcpSources.find(m=>m.name===entry.id)?.differingFields.length" class="model-error">各客户端同名定义不同，请明确采用来源。差异字段：{{catalog.mcpSources.find(m=>m.name===entry.id)?.differingFields.join('、')}}</p></template>

      <details v-if="entry.kind==='template'&&selected(entry)"><summary>选择确切保存版本 · {{scope?.selection.templateRefs.filter(r=>r.templateId===entry.id).length??0}} 个</summary><div v-for="reference in entry.revisions" :key="reference.revisionId"><label><input type="checkbox" :checked="scope?.selection.templateRefs.some(r=>r.templateId===reference.templateId&&r.revisionId===reference.revisionId&&r.digest===reference.digest)" :disabled="busy" @change="emit('revision',reference,($event.target as HTMLInputElement).checked)" />{{reference.revisionId}}</label><label><input type="checkbox" :checked="scope?.selection.adoptTemplateDefaults.some(r=>r.templateId===reference.templateId&&r.revisionId===reference.revisionId)" :disabled="busy||!scope?.selection.templateRefs.some(r=>r.templateId===reference.templateId&&r.revisionId===reference.revisionId)" @change="emit('default',reference,($event.target as HTMLInputElement).checked)" />明确采用此保存版本为默认</label></div><p>只同步已保存的模版版本，未保存修改不包含在内。</p></details>
    </template></template></ObjectScopeTree></section><aside class="sync-credentials" aria-label="其他凭据与内容保护"><h3>其他凭据</h3><p>按所选对象单独选择凭据，与内容保护口令独立。</p><template v-for="entry in entries.filter(selected)" :key="entry.kind+entry.id"><template v-if="entry.kind==='channel'"><label><input type="checkbox" :checked="channel(entry.id)?.includeKey" :disabled="busy||!entry.secretAvailable||channel(entry.id)?.familyIds!==null" @change="emit('option',entry.id,'includeKey',($event.target as HTMLInputElement).checked)" />{{entry.label}} · API Key</label><label><input type="checkbox" :checked="channel(entry.id)?.includeAuthorization" :disabled="busy||!entry.secretAvailable||channel(entry.id)?.familyIds!==null" @change="emit('option',entry.id,'includeAuthorization',($event.target as HTMLInputElement).checked)" />{{entry.label}} · 受支持授权</label></template><label v-if="entry.kind==='skill'||entry.kind==='mcp'"><input type="checkbox" :checked="entry.kind==='skill'?scope?.selection.extensionCredentials.skillNames.includes(entry.id):scope?.selection.extensionCredentials.mcpNames.includes(entry.id)" :disabled="busy||!entry.secretAvailable" @change="emit('credential',entry,($event.target as HTMLInputElement).checked)" />{{entry.label}} · 扩展凭据</label></template><label><input v-model="useProtection" type="checkbox" :disabled="busy" />加密同步内容</label><label v-if="useProtection">保护口令<input v-model="writePassphrase" class="input" type="password" autocomplete="new-password" aria-label="写入保护口令" /></label><details><summary>读取受保护的云端内容</summary><label>保护口令<input v-model="readPassphrase" class="input" type="password" autocomplete="off" aria-label="读取云端口令" /></label><p>仅在云端内容已设置保护时填写，与连接密码独立。</p></details></aside></div>

    <details class="sync-advanced"><summary>高级选项</summary><p>全局设置包含模版引用、默认渠道和渠道组顺序。勾选后按本次来源更新对应设置；未勾选时保留目标设备这些设置。</p><label><input type="checkbox" :checked="scope?.selection.includeGlobalTemplateRefs" :disabled="busy" @change="emit('global',($event.target as HTMLInputElement).checked)" />同步这些全局设置</label></details>
  </section>
  <UiDialog v-if="!workspace&&open" :open="open" title="同步预览" wide panel-class="config-sync-preview-v2" @close="emit('close')">
    <p v-if="busy" role="status">正在读取所选配置并计算变化，确认暂不可用。</p><p v-if="error" class="model-error" role="alert">{{errorMessage(error)}}</p><p v-if="stale" class="model-error" role="alert">来源、范围、端点或内容已变化，请重新预览；旧确认保持失效。</p>
    <template v-if="preview">
      <dl class="sync-preview-facts"><dt>本次来源</dt><dd><UiSelectField :model-value="preview.chosenDirection==='download'?'download':'upload'" label="本次同步来源" :disabled="busy" :options="[{value:'upload',label:'本机配置 → 云端（上传）'},{value:'download',label:'云端配置 → 本机（下载）'}]" @update:model-value="emit('direction',$event as 'upload'|'download')" /></dd><dt>本机保存时间</dt><dd>{{savedTime(preview.localSavedTime)}}</dd><dt>云端保存时间</dt><dd>{{savedTime(preview.cloudSavedTime)}}</dd></dl>
      <p role="status">{{reasonText[preview.automaticReason]}}</p>
      <p v-if="initialization">此目录尚未初始化。确认后才创建本次初始化代次并上传所选配置；预览、切换来源和取消不会写云端。</p>
      <label v-if="preview.chosenDirection==='download'&&!preview.noChange" class="sync-backup"><input type="checkbox" :checked="preview.backupBeforeUpdate" :disabled="busy" @change="emit('backup',($event.target as HTMLInputElement).checked)" />更新前备份</label>
      <h3>本次变化 · {{preview.entries.length}} 项</h3><ul class="sync-preview-diffs"><li v-for="entry in preview.entries" :key="entry.kind+entry.id"><strong>{{label(entry.kind,entry.id)}}</strong><span>{{changes[entry.status]}}</span></li></ul>
      <p v-if="preview.noChange||preview.plan.kind==='no_change'">所选内容没有需要写入的变化，不创建业务写入、备份或远端提交。</p>
      <p>只更新已确认所选范围，未选对象和凭据保持。下载确认时会结束未修改的模型编辑会话，有未保存输入时将停止。切换来源将重新只读 prepare，不直接执行。</p>
    </template>
    <template #actions="{close}"><UiButton @click="close">取消</UiButton><UiButton v-if="error||stale" :disabled="busy" @click="emit('retry')">重新预览</UiButton><UiButton variant="primary" :disabled="disabled" :loading="busy" @click="emit('confirm')">{{actionLabel}}</UiButton></template>
  </UiDialog>
</template>
<style scoped>
.config-sync-workspace-v2{display:grid;align-content:start;gap:16px;min-width:0}.sync-workspace-toolbar,.sync-workspace-toolbar>div:last-child,.sync-scope-heading,.sync-workspace-options{display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap}.config-sync-workspace-v2 label{display:flex;align-items:center;gap:8px;min-width:0}.config-sync-workspace-v2 input[type=search],.config-sync-workspace-v2 input[type=password]{min-width:0;max-width:100%}.sync-scope-list>article{display:grid;gap:12px;padding:14px 0;border-bottom:1px solid var(--border)}.sync-scope-heading>span,.sync-scope-heading label>span{color:var(--muted)}.sync-model-subset{max-height:240px;overflow:auto;display:grid;gap:8px}.sync-model-subset code{overflow-wrap:anywhere}.config-sync-workspace-v2 details p{overflow-wrap:anywhere}.sync-workspace-footer{display:flex;justify-content:flex-end}.config-sync-workspace-v2 h2{font-size:var(--text-subtitle);margin:0}.config-sync-workspace-v2 h2+p{margin-bottom:0;color:var(--muted)}
.sync-preview-facts{display:grid;grid-template-columns:100px minmax(0,1fr);gap:10px 16px}.sync-preview-facts dt{color:var(--muted)}.sync-preview-facts dd{margin:0;overflow-wrap:anywhere}.sync-preview-diffs{list-style:none;padding:0;margin:0}.sync-preview-diffs li{display:flex;justify-content:space-between;gap:12px;padding:12px 0;border-bottom:1px solid var(--border)}.sync-preview-diffs strong{overflow-wrap:anywhere;min-width:0;font-weight:var(--weight-medium)}.sync-preview-diffs span{flex:none;color:var(--muted)}.sync-backup{display:flex;align-items:center;gap:8px}.model-error{color:var(--red)}p{line-height:1.6}h3{font-size:var(--text-body)}@media(max-width:560px){.sync-preview-facts{grid-template-columns:minmax(0,1fr)}}
.sync-scope{display:grid;align-content:start;gap:var(--space-3);min-width:0}.sync-search{display:flex;min-width:0}.sync-search>.input{height:var(--control-md);flex:1;width:100%;min-width:140px}.sync-scope-workspace{display:grid;grid-template-columns:minmax(0,1fr) 220px;gap:20px;min-width:0}.sync-credentials{border-inline-start:1px solid var(--border);padding-inline-start:18px;min-width:0}.sync-credentials h3{margin:0}.sync-credentials label{display:flex;align-items:center;gap:8px;margin:14px 0}.sync-credentials label:has(input[type=password]){display:grid}.sync-credentials p{color:var(--muted)}.sync-workspace-actions{display:flex;gap:8px;align-items:center}.sync-more{position:relative}.sync-more>summary{list-style:none;cursor:pointer}.sync-more>summary::-webkit-details-marker{display:none}.sync-more-actions{position:absolute;right:0;top:calc(100% + 4px);z-index:5;min-width:160px;padding:8px;border:1px solid var(--border);border-radius:var(--radius-sm);background:var(--panel);box-shadow:var(--shadow)}@media(max-width:760px){.sync-scope-workspace{grid-template-columns:minmax(0,1fr)}.sync-credentials{border-inline-start:0;padding-inline-start:0;border-top:1px solid var(--border);padding-top:12px}}
</style>
